    ["Natural speech needs a local voice, so {setting} was switched to {voice}."] = "A természetes beszédhez helyi hang kell, ezért a beállítás ({setting}) erre váltott: {voice}.",
    ["Next"] = "Következő",
    ["No clear, reachable companion space on this floor. Move to a wider spot and try again."] = "Nincs szabad, elérhető hely a társnak ezen a szinten. Menj egy tágasabb helyre, és próbáld újra.",
    ["No conversation profile. This model joins as a follower without AI conversations."] = "Nincs beszélgetési profil. Ez a modell követőként csatlakozik MI-beszélgetések nélkül.",
    ["No entries are available."] = "Nincsenek elérhető bejegyzések.",
    ["No entries yet.\nTry another search or tab."] = "Még nincs találat.\nPróbálj másik keresést vagy lapot.",
    ["No matches. Try another name or clear the search."] = "Nincs egyezés. Próbálj másik nevet, vagy töröld a keresést.",
    ["No reply arrived. The conversation service may not be running."] = "Nem érkezett válasz. Lehet, hogy a beszélgetési szolgáltatás nem fut.",
    ["No reply received. Your message is in the draft; press Enter to retry."] = "Nem érkezett válasz. Az üzeneted a vázlatban van; nyomj Entert az újrapróbáláshoz.",
    ["No settings were supplied."] = "Nem lettek megadva beállítások.",
