    ["Return to conversation settings."] = "Vissza a beszélgetési beállításokhoz.",
    ["Return to the memory controls."] = "Vissza az emlékvezérlőkhöz.",
    ["Review the memory clear below, then choose Confirm or Cancel."] = "Nézd át az alábbi emléktörlést, majd válaszd a Megerősítés vagy a Mégse lehetőséget.",
    ["Romantic"] = "Romantikus",
    ["Running"] = "Fut",
    ["SELECTED"] = "KIVÁLASZTVA",
    ["SETTINGS"] = "BEÁLLÍTÁSOK",
    ["Save a report file you can send to the developer. API keys, tokens, IDs, microphone audio and conversation text are left out. If the conversation service is not running, a shorter report is made from the files the game can read."] = "Mentsd el a fejlesztőnek elküldhető jelentésfájlt. Az API-kulcsok, tokenek, azonosítók, mikrofonhang és beszélgetésszöveg kimaradnak belőle. Ha a beszélgetési szolgáltatás nem fut, rövidebb jelentés készül a játék által olvasható fájlokból.",
    ["Saved Chat cleanup could not be verified. Please wait for the memory service."] = "A mentett csevegés takarítását nem sikerült ellenőrizni. Várd meg az emlékszolgáltatást.",
    ["Saved at {path}"] = "Mentve ide: {path}",
    ["Saved reports"] = "Mentett jelentések",
    ["Scenery or a vehicle is blocking the companion position."] = "Díszlet vagy jármű blokkolja a társ pozícióját.",
    ["Search a character by name. Each invitation reserves a place and starts preparation immediately."] = "Keress karaktert név szerint. Minden meghívás helyet foglal, és azonnal elindítja az előkészítést.",
    ["Search by character name or model record using Search settings. {query}"] = "Keress karakternév vagy modellrekord szerint a Keresés beállítással. {query}",
    ["Search by character name using Search settings. {query}\nThe character can be outside your current party."] = "Keress karakternév szerint a Keresés beállítással. {query}\nA karakter lehet a jelenlegi csapatodon kívül is.",
    ["Search names, models or settings..."] = "Keresés nevek, modellek vagy beállítások között...",
    ["Select a destination on the map first."] = "Előbb válassz úticélt a térképen.",
    ["Select {name} for memory controls. This does not invite them or change their conversation settings."] = "{name} kiválasztása az emlékek kezeléséhez. Ez nem hívja meg, és nem módosítja a beszélgetési beállításait.",
    ["Selected"] = "Kiválasztva",
    ["Selected character"] = "Kiválasztott karakter",
    ["Send the generated report rather than raw log files. Open these locations only if the developer asks for a specific file."] = "A létrehozott jelentést küldd el, ne a nyers naplófájlokat. Ezeket a helyeket csak akkor nyisd meg, ha a fejlesztő konkrét fájlt kér.",
    ["Settings"] = "Beállítások",
