    ["{name} will say one of their game lines when you return to the game."] = "{name} elmondja egyik játékbeli mondatát, amikor visszatérsz a játékba.",
    ["Lip sync delay (Bluetooth)"] = "Szájszinkron késleltetés (Bluetooth)",
    ["Bluetooth earbuds and headphones play sound a little later than the picture, so lips and subtitles can run slightly ahead of the voice. This holds them back to match, for every voice. Auto uses 150 ms while Windows plays through a Bluetooth device and none otherwise; choose a value if your headset is faster or slower. The game’s own dialogue has the same Bluetooth delay and does not correct it."] = "A Bluetooth fül- és fejhallgatók a hangot kicsit később játsszák le, mint a képet, ezért az ajkak és a feliratok enyhén megelőzhetik a hangot. Ez visszatartja őket, hogy egyezzenek, minden hangnál. Az automatikus mód 150 ms-ot használ, amíg a Windows Bluetooth eszközön játszik le, különben semmit; válassz értéket, ha a fejhallgatód gyorsabb vagy lassabb. A játék saját párbeszédeinek ugyanilyen a Bluetooth késése, és a játék nem javítja.",
    ["Choose one of the listed lip sync delays."] = "Válassz egyet a felsorolt szájszinkron késleltetések közül.",
    ["Behavior: {list}"] = "Viselkedés: {list}",
    ["In your party: {count}"] = "A csapatodban: {count}",
    ["Memory: remembers your conversations"] = "Emlékek: emlékszik a beszélgetéseitekre",
    ["Multilingual: replies in your language"] = "Többnyelvű: a te nyelveden válaszol",
    ["Relationship: {mode}"] = "Kapcsolat: {mode}",
    ["Speech: {list}"] = "Beszéd: {list}",
    ["Added"] = "Hozzáadva",
    ["Added (ends in {tail})"] = "Hozzáadva (a vége: {tail})",
    ["Checking…"] = "Ellenőrzés…",
    ["Convai API key"] = "Convai API-kulcs",
    ["Convai did not accept that key."] = "A Convai nem fogadta el ezt a kulcsot.",
    ["Convai did not accept your API key. Check it in Settings > Development."] = "A Convai nem fogadta el az API-kulcsodat. Ellenőrizd a Beállítások > Fejlesztés menüpontban.",
    ["Conversations use"] = "Beszélgetések használata",
    ["Copy your key on convai.com first. It is read from the clipboard once, checked with Convai and saved on this computer."] = "Először másold ki a kulcsodat a convai.com oldalról. A vágólapról egyszer olvassuk be, a Convai ellenőrzi, és ezen a számítógépen mentjük.",
    ["Deletes the saved key. Conversations go back to the shared plan."] = "Törli a mentett kulcsot. A beszélgetések visszatérnek a közös csomaghoz.",
    ["Not added"] = "Nincs hozzáadva",
    ["Paste Convai API key"] = "Convai API-kulcs beillesztése",
    ["Paste from clipboard"] = "Beillesztés a vágólapról",
    ["Remove"] = "Eltávolítás",
    ["Remove my Convai API key"] = "Convai API-kulcsom eltávolítása",
    ["Saved on this computer only. Only the last four characters are ever shown."] = "Csak ezen a számítógépen van mentve. Mindig csak az utolsó négy karakter látszik.",
    ["Shared plan: daily limit reached"] = "Közös csomag: a napi keret elfogyott",
    ["Shared plan: limit used up"] = "Közös csomag: a keret elfogyott",
    ["The clipboard could not be read."] = "A vágólapot nem sikerült beolvasni.",
    ["The clipboard does not hold a Convai API key."] = "A vágólapon nincs Convai API-kulcs.",
    ["The clipboard is empty. Copy your key first."] = "A vágólap üres. Előbb másold ki a kulcsodat.",
    ["The conversation limit has been reached. Get a free API key at convai.com, then add it in Settings > Development."] = "Elérted a beszélgetési keretet. Szerezz ingyenes API-kulcsot a convai.com oldalon, majd add meg a Beállítások > Fejlesztés menüpontban.",
    ["The key could not be saved."] = "A kulcsot nem sikerült menteni.",
    ["The request could not be sent. Try again."] = "A kérést nem sikerült elküldeni. Próbáld újra.",
    ["The shared plan"] = "A közös csomag",
    ["The shared plan: {left} of {limit} left today"] = "A közös csomag: ma még {left} maradt a {limit} keretből",
    ["Use my own Convai API key"] = "Saját Convai API-kulcs használata",
    ["Want more conversations? The shared plan has a daily conversation limit, and there are two free ways to keep talking. Convai (recommended, better quality responses): get a free API key at convai.com, copy it, choose Paste Convai API key below, turn this on and choose Apply. A free Convai plan has a small monthly allowance, one connection at a time and only a few memory users, so companions open one at a time and Multilingual conversations and memory management are unavailable. Mistral (free; signup needs phone verification): get a free key at console.mistral.ai, copy it, choose Paste Mistral key, then set Conversation provider to Mistral and choose Apply. Memory stays on this computer. The change waits until no conversation is running."] = "Több beszélgetést szeretnél? A közös csomagnak napi beszélgetési kerete van, és kétféleképpen folytathatod ingyen. Convai (ajánlott, jobb minőségű válaszokkal): szerezz ingyenes API-kulcsot a convai.com oldalon, másold ki, válaszd lent a Convai API-kulcs beillesztése lehetőséget, kapcsold be ezt, és válaszd az Alkalmaz gombot. Az ingyenes Convai csomag kis havi kerettel, egyszerre csak egy kapcsolattal és csak néhány memóriahasználónak elegendő helyet ad, ezért a társak egyesével nyílnak meg, a többnyelvű beszélgetések és a memóriakezelés pedig nem érhető el. Mistral (ingyenes; a regisztrációhoz telefonos ellenőrzés szükséges): szerezz ingyenes kulcsot a console.mistral.ai oldalon, másold ki, válaszd a Mistral-kulcs beillesztése lehetőséget, majd a Beszélgetésszolgáltató beállítást állítsd Mistralra, és válaszd az Alkalmaz gombot. A memória ezen a számítógépen marad. A módosítás akkor lép életbe, ha nem fut beszélgetés.",
    ["Your Convai API key has reached its plan limit. Try again later or add a different key in Settings > Development."] = "A Convai API-kulcsod elérte a csomag keretét. Próbáld újra később, vagy adj meg másik kulcsot a Beállítások > Fejlesztés menüpontban.",
    ["Your key was removed."] = "A kulcsodat eltávolítottuk.",
    ["Your key: not accepted"] = "A kulcsod: nem fogadta el",
    ["Your key: plan limit reached"] = "A kulcsod: elérte a csomag keretét",
    ["Your own key"] = "Saját kulcs",
    ["Your Convai plan cannot hold the memory these conversations need. Free a memory user in your Convai account or use another key."] = "A Convai csomagod nem tudja tárolni azt a memóriát, amelyre ezeknek a beszélgetéseknek szükségük van. Szabadíts fel egy memóriahasználót a Convai-fiókodban, vagy használj másik kulcsot.",
    ["Your Convai plan has no room for conversation memory, so companions will not remember past talks."] = "A Convai csomagodban nincs hely a beszélgetések memóriájának, ezért a társak nem fogják emlékezni a korábbi beszélgetésekre.",
    ["Your key: no room for memory"] = "A kulcsod: nincs hely a memóriának",
    ["Your own key, without memory"] = "Saját kulcs, memória nélkül",
    ["You’ve reached today’s free conversation limit. Add your own free Convai API key (recommended, better quality responses) or a free Mistral key (signup needs phone verification) in Settings > Development to keep talking."] = "Elérted a mai ingyenes beszélgetési keretet. Add meg a saját ingyenes Convai API-kulcsodat (ajánlott, jobb minőségű válaszokkal) vagy egy ingyenes Mistral-kulcsot (a regisztrációhoz telefonos ellenőrzés szükséges) a Beállítások > Fejlesztés menüpontban, hogy tovább beszélgethess.",
}
